use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,io::Read,path::Path,process::{Command,Stdio}};
use std::os::unix::fs::FileTypeExt;
fn hash(p:&Path)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){assert!(src.symlink_metadata().unwrap().file_type().is_file(),"nonregular {}",src.display());fs::create_dir_all(dst.parent().unwrap()).unwrap();let digest=if src.file_name().is_some_and(|n|n=="perf.data"){let before=fs::metadata(src).unwrap();let result=Command::new("sudo").args(["-n","sha256sum"]).arg(src).output().unwrap();assert!(result.status.success());let digest=String::from_utf8(result.stdout).unwrap().split_whitespace().next().unwrap().to_owned();let output=fs::File::create(dst).unwrap();assert!(Command::new("sudo").args(["-n","cat"]).arg(src).stdout(Stdio::from(output)).status().unwrap().success());let after=fs::metadata(src).unwrap();assert_eq!(before.len(),after.len());assert_eq!(before.modified().unwrap(),after.modified().unwrap());digest}else{fs::copy(src,dst).unwrap();hash(src)};assert_eq!(hash(dst),digest);assert!(index.insert(dst.strip_prefix(root).unwrap().to_str().unwrap().into(),digest).is_none());}
fn tree(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){let mut entries=fs::read_dir(src).unwrap().map(|e|e.unwrap().path()).collect::<Vec<_>>();entries.sort();for p in entries{let name=p.file_name().unwrap();if name=="target"{continue}let q=dst.join(name);let kind=p.symlink_metadata().unwrap().file_type();if kind.is_dir(){tree(&p,&q,root,index)}else if kind.is_fifo(){assert!(["ctl","ack"].iter().any(|n|name==*n));}else if name!="candidate-sdk"{copy(&p,&q,root,index)}}}
fn main(){let src=Path::new("/tmp/zopro-front-snapshot-fence");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-front-snapshot-fence");let dst=report.join("artifacts");assert!(!dst.exists());let mut index=BTreeMap::new();for name in ["experiment.json","accepted-manifest.json","prepare.json","native-plan.json","build-input-pins.json","native.log","implement.rs","prepare-build.rs","upstream-deque.rs","upstream-registry.rs","upstream-pins.json","lock-audit.json","source-audit.rs","source-audit.json","ordering-review.md","source.patch","registry.patch","registry-audit.rs","registry-audit.json","registry-input-pins.json","model-tests.log","model-lock.log","deque-lock.log","rayon-lock.log","prepare-protocol-source.rs","make-protocol.rs","make-protocol.log","linked-scheduler-libraries.json","all-nine-template.json","perf-template.json","perf-template-with-pins.json","perf-plan.json","input-pins.json","preflight-plan.json","inventory-preflight.sh","validate-preflight.jq","preflight-validation.json","preflight-proof-inventory.json","preflight.log","perf.log","analyze.rs","analyze-tests.log","pilot-result.json","closeout.rs","closeout.json","proof-inventory.json","codegen.rs","codegen-review.json","codegen.txt","next-design.md","write-report.rs","work-state.json","publish.rs","research/source-pins.json","research/notes.md"]{copy(&src.join(name),&dst.join(name),&dst,&mut index)}for name in ["candidate","model","native","preflight","preflight-proofs","perf"]{tree(&src.join(name),&dst.join(name),&dst,&mut index)}let raw=index.keys().filter(|p|p.ends_with("/perf.data")).count();let symbols=index.keys().filter(|p|p.ends_with("/symbols/stdout.log")).count();assert_eq!(raw,9);assert_eq!(symbols,9);let member=|p:&&String|p.ends_with(".proof")||p.ends_with(".public");let members=index.keys().filter(|p|(p.starts_with("perf/")||p.starts_with("preflight-proofs/"))&&member(p)).count();let fixtures=index.keys().filter(|p|p.starts_with("candidate/")&&member(p)).count();assert_eq!(members,474);assert_eq!(fixtures,2);let research:Value=serde_json::from_slice(&fs::read(src.join("research/source-pins.json")).unwrap()).unwrap();for(p,h)in research.as_object().unwrap(){assert_eq!(hash(Path::new(p)),h.as_str().unwrap());}let sums=index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>();fs::write(dst.join("SHA256SUMS"),sums).unwrap();fs::write(dst.join("artifact-index.json"),format!("{}\n",serde_json::to_string_pretty(&json!({"files":index.len(),"proof_public_members":members,"additional_source_fixture_members":fixtures,"raw_perf":raw,"expanded_symbols":symbols,"external_local_research_inputs":research,"sha256":index,"scope":"Archived frozen sources/config/test/proof/measurement copies. Nine raw captures and nine expanded streams are retained locally, ignored Git. Executables/compiler caches represented by exact build/link hashes. Research PDF/full HTML remain in original local paths with primary URLs and hashes only, not copied into archive or Git."})).unwrap())).unwrap();fs::write(report.join(".gitignore"),"/artifacts/**/perf.data\n/artifacts/**/symbols/stdout.log\n").unwrap();fs::write(report.join(".gitattributes"),"# Preserve exact archived source and output bytes.\nartifacts/** -whitespace\n").unwrap();println!("ARCHIVE_VERIFIED {}files474newproof/public2sourcefixtures9raw9expanded",index.len());}
